26	/** Least-loaded enabled+online Proxmox node by RAM headroom (mirrors lib/order.ts scheduleNode). */
27	async function scheduleNode(planRamMB: number): Promise<string | null> {
28	  const nodes = await db.node.findMany({ where: { enabled: true, status: "ONLINE" } });
29	  if (nodes.length === 0) return null;
30	  const loads = await Promise.all(
31	    nodes.map(async (n) => {
32	      const agg = await db.server.findMany({
33	        where: { nodeId: n.id, status: { notIn: ["DELETING"] } },
34	        select: { plan: { select: { ramMB: true } } },
35	      });
36	      const used = agg.reduce((s, r) => s + r.plan.ramMB, 0);
37	      return { id: n.id, free: n.capacityRamMB - used };
38	    }),
39	  );
40	  loads.sort((a, b) => b.free - a.free);
41	  return loads[0].id;
42	}
