44	/**
45	 * Order a managed Nextcloud (NxCloud) instance.
46	 *
47	 * MONEY SAFETY — this mirrors the audited VPS/hosting order discipline:
48	 *   - no spending while impersonating; verified email required;
49	 *   - the wallet is charged the FULL displayed monthly price (NO first-month-free —
50	 *     that promo is shared-hosting only), in the SAME transaction that creates the
51	 *     records, so a rolled-back charge leaves no instance and no invoice;
52	 *   - the amount charged is exactly `plan.priceCents`, which is also what the
53	 *     backing Server renews at (its `serverPlan.priceCents` is seeded equal), so
54	 *     displayed === charged === renewed.
55	 *
56	 * The instance is backed by a real `Server`, created here with a PROVISION job.
57	 * The worker clones/sizes the VM and bakes in the Nextcloud install (worker/nxcloud.ts);
58	 * the instance flips to ACTIVE once it verifies serving.
59	 */
60	export async function orderNxCloud(planId: string, subdomainRaw: string): Promise<NxCloudResult> {
61	  const user = await requireUser();
62	  await assertNotImpersonating();
63	  const unverified = await emailVerificationError(user);
64	  if (unverified) return { error: unverified };
65	
66	  const subdomain = normalizeSubdomain(subdomainRaw);
67	  if (!subdomain) return { error: "Choose a subdomain for your cloud." };
68	  if (!isValidSubdomainLabel(subdomain)) {
69	    return { error: "Subdomain: 3–32 lowercase letters, digits or hyphens (not a reserved word)." };
70	  }
71	
72	  const plan = await db.nxCloudPlan.findUnique({ where: { id: planId }, include: { serverPlan: true } });
73	  if (!plan || !plan.active) return { error: "That NxCloud plan isn’t available." };
74	  if (!plan.serverPlan) return { error: "This plan isn’t fully configured yet — please contact support." };
75	
76	  // The Nextcloud OS image the VM clones from (seeded by prisma/seed-nxcloud.ts).
77	  const osTemplate = await db.osTemplate.findUnique({ where: { slug: "nextcloud" } });
78	  if (!osTemplate) return { error: "NxCloud isn’t available yet — the Nextcloud image hasn’t been seeded." };
79	
80	  // Subdomain is globally unique across all customers (it's a public hostname).
81	  const taken = await db.nxCloudInstance.findFirst({
82	    where: { subdomain, status: { in: [...LIVE_STATES] } },
83	    select: { id: true, userId: true },
84	  });
85	  if (taken) {
86	    return {
87	      error:
88	        taken.userId === user.id
89	          ? "You already have a cloud with that subdomain."
90	          : "That subdomain is taken — try another.",
91	    };
92	  }
93	
94	  const chargeCents = plan.priceCents;
95	  if (user.balanceCents < chargeCents) return { error: "Insufficient balance. Top up your wallet first." };
96	
97	  const nodeId = await scheduleNode(plan.serverPlan.ramMB);
98	  const zone = (await getSetting("nxcloud_zone", NXCLOUD_DEFAULT_ZONE)).trim() || NXCLOUD_DEFAULT_ZONE;
99	  const fqdn = nxcloudFqdn(subdomain, zone);
100	
101	  let instanceId = "";
102	  try {
103	    await db.$transaction(async (tx) => {
104	      await debitWallet(tx, user.id, chargeCents);
105	      await tx.walletTransaction.create({
106	        data: {
107	          userId: user.id,
108	          amountCents: -chargeCents,
109	          description: `NxCloud: ${plan.name} (${fqdn})`,
110	        },
111	      });
112	      await tx.invoice.create({
113	        data: invoiceCreateData({
114	          userId: user.id,
115	          description: `NxCloud: ${plan.name} (${fqdn})`,
116	          status: "PAID",
117	          period: { start: new Date(), end: addMonths(new Date(), 1) },
118	          lineItems: [
119	            { description: `${plan.name} — managed Nextcloud (${fqdn})`, qty: 1, unitCents: chargeCents, amountCents: chargeCents },
120	          ],
121	        }),
122	      });
123	      // The backing VM. A normal Server — it renews / duns / suspends / monitors
124	      // through the exact same audited machinery as a VPS. VM snapshot backups are
125	      // ON by default (data-loss safety, spec §6); a public IP is requested so the
126	      // instance is reachable by hostname for auto-TLS.
127	      const server = await tx.server.create({
128	        data: {
129	          name: subdomain,
130	          hostname: subdomain,
131	          userId: user.id,
132	          planId: plan.serverPlanId,
133	          osTemplateId: osTemplate.id,
134	          nodeId,
135	          autoBackup: true,
136	          backupIntervalHours: 24,
137	          termMonths: 1,
138	          // Sold at full price — 0% off — so no later proration can claw a discount
139	          // that was never given (see Server.termPromoPercent).
140	          termPromoPercent: 0,
141	          wantsDedicatedIp: true,
142	          isFree: false,
143	          expiresAt: addMonths(new Date(), 1),
144	        },
145	      });
146	      const inst = await tx.nxCloudInstance.create({
147	        data: {
148	          userId: user.id,
149	          planId: plan.id,
150	          serverId: server.id,
151	          subdomain,
152	          status: "PENDING",
153	          adminUser: "admin",
154	          storageQuotaMB: plan.storageGB * 1024,
155	        },
156	      });
157	      instanceId = inst.id;
158	      await tx.job.create({ data: { type: "PROVISION", serverId: server.id } });
159	    });
160	  } catch (e) {
161	    if (e instanceof InsufficientBalanceError) return { error: "Insufficient balance. Top up your wallet first." };
162	    return { error: "Couldn’t place the order. Your wallet was not charged — try again." };
163	  }
164	
165	  await db.auditLog
166	    .create({ data: { userId: user.id, action: "nxcloud.order", detail: `${plan.name} · ${fqdn}` } })
167	    .catch(() => {});
168	  revalidatePath("/dashboard/nxcloud");
169	  return { ok: true, instanceId };
170	}
