190	function toView(
191	  a: {
192	    id: string; subdomain: string; customDomain: string | null; status: string; adminUser: string;
193	    adminPassEnc: string | null; storageQuotaMB: number; storageUsedMB: number | null; usageAt: Date | null;
194	    sslActive: boolean; version: string | null; error: string | null; createdAt: Date;
195	    plan: { name: string }; server: { expiresAt: Date | null } | null;
196	  },
197	  zone: string,
198	): NxCloudInstanceView {
