209	    storageUsedMB: a.storageUsedMB ?? null,
210	    usageAt: a.usageAt?.toISOString() ?? null,
211	    sslActive: a.sslActive,
212	    version: a.version,
213	    error: a.error,
214	    expiresAt: a.server?.expiresAt?.toISOString() ?? null,
215	    createdAt: a.createdAt.toISOString(),
216	  };
217	}
