219	/** The current user's NxCloud instances (newest first). */
220	export async function listNxcloudInstances(): Promise<NxCloudInstanceView[]> {
221	  const user = await requireUser();
222	  const zone = (await getSetting("nxcloud_zone", NXCLOUD_DEFAULT_ZONE)).trim() || NXCLOUD_DEFAULT_ZONE;
223	  const rows = await db.nxCloudInstance.findMany({
224	    where: { userId: user.id },
225	    include: { plan: { select: { name: true } }, server: { select: { expiresAt: true } } },
226	    orderBy: { createdAt: "desc" },
227	  });
228	  return rows.map((r) => toView(r, zone));
229	}
