231	/**
232	 * Reveal the current Nextcloud admin password to the OWNER (or an admin who is NOT
233	 * impersonating). Same discipline as the SFTP-password reveal in
234	 * lib/actions-hosting.ts — an impersonating admin must never exfiltrate it.
235	 */
236	export async function revealNxcloudAdminPassword(instanceId: string): Promise<{ password?: string; error?: string }> {
237	  const user = await requireUser();
238	  await assertNotImpersonating();
239	  const inst = await db.nxCloudInstance.findUnique({
240	    where: { id: instanceId },
241	    select: { userId: true, adminPassEnc: true },
242	  });
243	  if (!inst) return { error: "Not found." };
244	  if (inst.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
245	  const pw = inst.adminPassEnc ? decryptSecret(inst.adminPassEnc) : null;
246	  if (!pw) return { error: "No password on record yet — your cloud is still being set up." };
247	  return { password: pw };
248	}
