250	/** Queue an admin-password reset for an instance (worker regenerates + re-applies). */
251	export async function resetNxcloudAdminPassword(instanceId: string): Promise<NxCloudResult> {
252	  const user = await requireUser();
253	  await assertNotImpersonating();
254	  const inst = await db.nxCloudInstance.findUnique({ where: { id: instanceId }, select: { userId: true, status: true } });
255	  if (!inst) return { error: "Not found." };
256	  if (inst.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
257	  if (inst.status !== "ACTIVE") return { error: "Wait until your cloud is active, then reset the password." };
258	  await db.nxCloudTask.create({ data: { instanceId, kind: "RESET_ADMIN_PW" } });
259	  revalidatePath("/dashboard/nxcloud");
260	  return { ok: true };
261	}
262	
263	/**
264	 * Terminate an instance: destroy the backing VM (enqueue a Server DELETE — the
265	 * audited teardown that stops billing and purges the disk) and remove the
266	 * instance record. Irreversible; the customer's files go with the VM.
267	 */
268	export async function terminateNxcloud(instanceId: string): Promise<NxCloudResult> {
269	  const user = await requireUser();
270	  await assertNotImpersonating();
271	  const inst = await db.nxCloudInstance.findUnique({ where: { id: instanceId }, select: { userId: true, serverId: true } });
272	  if (!inst) return { error: "Not found." };
273	  if (inst.userId !== user.id && user.role !== "ADMIN") return { error: "Forbidden." };
274	  if (inst.serverId) {
275	    await db.job.create({ data: { type: "DELETE", serverId: inst.serverId } });
276	  }
277	  // Drop the wrapper row (tasks cascade). The DELETE job tears the VM down.
278	  await db.nxCloudInstance.delete({ where: { id: instanceId } });
279	  await db.auditLog.create({ data: { userId: user.id, action: "nxcloud.terminate", detail: instanceId } }).catch(() => {});
280	  revalidatePath("/dashboard/nxcloud");
281	  return { ok: true };
282	}
