300	      server: { select: { expiresAt: true } },
301	      user: { select: { email: true } },
302	    },
303	    orderBy: { createdAt: "desc" },
304	  });
305	  return rows.map((r) => ({ ...toView(r, zone), userEmail: r.user.email, serverId: r.serverId }));
306	}
