164	function InstanceCard({ inst }: { inst: NxCloudInstanceView }) {
165	  const [pw, setPw] = useState<string | null>(null);
166	  const [msg, setMsg] = useState("");
167	  const [busy, setBusy] = useState(false);
168	
169	  async function reveal() {
170	    setBusy(true);
171	    const res = await revealNxcloudAdminPassword(inst.id);
172	    setBusy(false);
173	    if (res.error) setMsg(res.error);
174	    else setPw(res.password ?? "");
175	  }
176	  async function reset() {
177	    if (!confirm("Reset the Nextcloud admin password for this cloud?")) return;
178	    setBusy(true);
179	    const res = await resetNxcloudAdminPassword(inst.id);
180	    setBusy(false);
181	    setMsg(res.error ?? "Password reset queued — check back in a moment.");
182	    setPw(null);
183	  }
184	  async function terminate() {
185	    if (!confirm("Permanently delete this cloud and ALL its files? This cannot be undone.")) return;
186	    setBusy(true);
187	    const res = await terminateNxcloud(inst.id);
188	    setBusy(false);
189	    if (res.error) setMsg(res.error);
190	    else window.location.reload();
191	  }
192	
193	  const usedPct =
194	    inst.storageUsedMB != null && inst.storageQuotaMB > 0
195	      ? Math.min(100, Math.round((inst.storageUsedMB / inst.storageQuotaMB) * 100))
196	      : null;
197	
198	  return (
199	    <div className="card card-hover">
